sys_script_fix.script:
function populateTotalCost() {
	var almLicenseRecord = new GlideRecord('alm_license');
	almLicenseRecord.query();

	while (almLicenseRecord.next()) {
		almLicenseRecord.unit_cost = parseFloat(almLicenseRecord.cost)
			/ parseInt(almLicenseRecord.purchased_rights, 10);
		almLicenseRecord.update();
	}
}

populateTotalCost();
